-- -----------------------------------------------------
-- 0. EXTENSIONS & GLOBAL ENUMS
-- -----------------------------------------------------
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
DO $$ BEGIN
    CREATE TYPE gtd_stage AS ENUM ('inbox', 'clarify', 'organize', 'review', 'engage');
EXCEPTION
    WHEN duplicate_object THEN null;
END $$;
DO $$ BEGIN
    CREATE TYPE para_type AS ENUM ('project', 'area', 'resource', 'archive');
EXCEPTION
    WHEN duplicate_object THEN null;
END $$;
DO $$ BEGIN
    CREATE TYPE veto_status AS ENUM ('pending', 'approved', 'halted');
EXCEPTION
    WHEN duplicate_object THEN null;
END $$;
-- -----------------------------------------------------
-- 1-8. LES DOMAINES (LD)
-- -----------------------------------------------------
CREATE TABLE ld01_business (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  title TEXT NOT NULL,
  metrics JSONB DEFAULT '{}',
  created_at TIMESTAMPTZ DEFAULT now()
);
CREATE TABLE ld02_finance (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  title TEXT NOT NULL,
  metrics JSONB DEFAULT '{}',
  created_at TIMESTAMPTZ DEFAULT now()
);
CREATE TABLE ld03_health (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  title TEXT NOT NULL,
  metrics JSONB DEFAULT '{}',
  created_at TIMESTAMPTZ DEFAULT now()
);
CREATE TABLE ld04_cognition (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  title TEXT NOT NULL,
  metrics JSONB DEFAULT '{}',
  created_at TIMESTAMPTZ DEFAULT now()
);
CREATE TABLE ld05_environment (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  title TEXT NOT NULL,
  metrics JSONB DEFAULT '{}',
  created_at TIMESTAMPTZ DEFAULT now()
);
CREATE TABLE ld06_relationships (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  title TEXT NOT NULL,
  metrics JSONB DEFAULT '{}',
  created_at TIMESTAMPTZ DEFAULT now()
);
CREATE TABLE ld07_emotions (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  title TEXT NOT NULL,
  metrics JSONB DEFAULT '{}',
  created_at TIMESTAMPTZ DEFAULT now()
);
CREATE TABLE ld08_purpose (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  title TEXT NOT NULL,
  metrics JSONB DEFAULT '{}',
  created_at TIMESTAMPTZ DEFAULT now()
);
-- -----------------------------------------------------
-- 9-14. LES FRAMEWORKS (FW)
-- -----------------------------------------------------
-- Note on linked_ld_id: Since PostgreSQL FKs point to a single table, 
-- these are defined as loose UUIDs for polymorphic routing to any of the 8 LDs.
CREATE TABLE fw_life_wheel (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  title TEXT NOT NULL,
  metrics JSONB DEFAULT '{}',
  linked_ld_id UUID, -- Reference to ld01-ld08
  created_at TIMESTAMPTZ DEFAULT now()
);
CREATE TABLE fw_ikigai (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  title TEXT NOT NULL,
  stories JSONB DEFAULT '[]', -- Managing Stories via JSONB as requested
  linked_ld_id UUID,
  created_at TIMESTAMPTZ DEFAULT now()
);
CREATE TABLE fw_12wy (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  title TEXT NOT NULL,
  goals JSONB DEFAULT '[]',
  linked_ld_id UUID,
  created_at TIMESTAMPTZ DEFAULT now()
);
CREATE TABLE fw_para (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  title TEXT NOT NULL,
  type para_type NOT NULL DEFAULT 'resource',
  linked_ld_id UUID,
  metadata JSONB DEFAULT '{}',
  created_at TIMESTAMPTZ DEFAULT now()
);
CREATE TABLE fw_gtd (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  title TEXT NOT NULL,
  stage gtd_stage NOT NULL DEFAULT 'inbox',
  linked_ld_id UUID,
  metadata JSONB DEFAULT '{}',
  created_at TIMESTAMPTZ DEFAULT now()
);
CREATE TABLE fw_deal (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  title TEXT NOT NULL,
  definition JSONB DEFAULT '{}',
  linked_ld_id UUID,
  created_at TIMESTAMPTZ DEFAULT now()
);
-- -----------------------------------------------------
-- 15-16. SYSTEM CORE (SYS)
-- -----------------------------------------------------
CREATE TABLE sys_shell_routing (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  user_id UUID, -- Linked to auth.users if using Supabase Auth
  active_workspace TEXT NOT NULL DEFAULT 'default',
  last_saved_state JSONB DEFAULT '{}',
  updated_at TIMESTAMPTZ DEFAULT now()
);
CREATE TABLE sys_agent_veto (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  requesting_agent TEXT NOT NULL,
  payload JSONB DEFAULT '{}',
  status veto_status NOT NULL DEFAULT 'pending',
  created_at TIMESTAMPTZ DEFAULT now()
);
