            position: absolute;
            width: 40px;
            height: 40px;
            border: 4px solid var(--gold-color);
        }
        /* Top Left */
        .main-border::before { top: -14px; left: -14px; border-right: none; border-bottom: none; }
        /* Bottom Right */
        .main-border::after { bottom: -14px; right: -14px; border-left: none; border-top: none; }
        /* --- Contenu du Diplôme (Flexbox) --- */
        .content {
            height: 100%;
            display: flex;
            flex-direction: column;
            justify-content: space-between; /* Espace équilibré haut/bas */
            align-items: center;
            text-align: center;
            position: relative;
            z-index: 10;
        }
        /* --- Stylisation du Texte --- */
        .header-org {
