        }
        .preamble {
            font-style: italic;
            font-size: 16px;
            max-width: 70%;
            line-height: 1.4;
            margin-bottom: 15px;
        }
        .award-title-label {
            font-size: 20px;
            margin-bottom: 2px;
        }
        .award-title {
            font-family: var(--font-title);
            font-size: 32px;
            font-weight: 500;
            text-transform: uppercase;
            letter-spacing: 1px;
            border-bottom: 1px solid var(--gold-color);
            padding-bottom: 5px;
            margin-bottom: 15px;
        }
        .recipient-label {
            font-size: 18px;
            margin-bottom: 2px;
        }
        .recipient-name {
            font-family: var(--font-title);
            font-size: 54px;
            font-weight: 700;
            color: var(--text-color);
            letter-spacing: 1px;
            margin: 0;
        }
        .mention {
            font-size: 18px;
            max-width: 65%;
            line-height: 1.5;
            margin-top: 15px;
            font-weight: 500;
        }
        .date-location {
            font-size: 16px;
            margin-top: 25px;
        }
        /* --- Zone de Signature & Sceau (Grid) --- */
        .signatures-area {
            width: 100%;
            display: grid;
            grid-template-columns: 1fr auto 1fr; /* [Sign1] [Sceau] [Sign2] */
            align-items: end;
            margin-top: 30px;
        }
        .signature-block {
            display: flex;
            flex-direction: column;
            align-items: center;
        }
        .signature-line {
            width: 200px;
            border-top: 1px solid var(--text-color);
            margin-bottom: 8px;
        }
        .signature-name {
            font-weight: 600;
            font-size: 16px;
        }
        .signature-title {
            font-style: italic;
            font-size: 14px;
        }
        /* --- Sceau CSS --- */
        .seal-container {
            width: 120px;
            height: 120px;
            display: flex;
            justify-content: center;
            align-items: center;
            position: relative;
        }
        .seal {
            width: 100px;
            height: 100px;
            border-radius: 50%;
            background: radial-gradient(circle, #e6c67d 0%, var(--gold-color) 100%);
            border: 3px double #b08b3e; /* Effet cire gravée */
            box-shadow: 2px 2px 5px rgba(0,0,0,0.2), inset 0 0 15px rgba(0,0,0,0.1);
            display: flex;
            justify-content: center;
            align-items: center;
            text-align: center;
        }
        .seal::after {
            content: 'OFFICIEL'; /* Texte simulé dans le sceau */
